//! Search engines the user can choose from, and how to turn one into an HTML form (the new-tab
//! page searches with a plain form, no scripts).

use url::Url;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Engine {
    pub id: &'static str,
    pub name: &'static str,
    /// Search URL, `%s` is the query.
    pub template: &'static str,
    /// The colour behind the badge, and the engine's glyph in it: the `viewBox` and the path of
    /// a one-colour mark (from the Simple Icons set, CC0; Bing's from its own site's logo).
    pub color: &'static str,
    pub view: &'static str,
    pub glyph: &'static str,
}

